import json
import re

def tool_call_parser(llm_response, tool_schemas):
    schema_map = {s["name"]: s for s in tool_schemas}
    json_match = re.search(r"```(?:json)?\s*(.*?)\s*```", llm_response, re.DOTALL)
    if json_match:
        raw = json_match.group(1)
    else:
        raw = llm_response
    try:
        call = json.loads(raw)
    except json.JSONDecodeError:
        return {"error": "Invalid JSON", "raw": llm_response}
    tool_name = call.get("tool", call.get("name"))
    if tool_name not in schema_map:
        return {"error": f"Unknown tool: {tool_name}"}
    schema = schema_map[tool_name]
    args = call.get("arguments", call.get("params", {}))
    for param in schema.get("params", {}):
        if param not in args:
            return {"error": f"Missing parameter: {param}"}
    return {"tool": tool_name, "arguments": args}
